select top 10 *
from cleaned_data;

-- What is the total revenue generated by male vs female customers?
select gender,
sum(purchased_amount) as total_revenue
from cleaned_data
group by gender;

-- Which customer used a discount but still spent more than average purchase amount?
select customer_id, purchased_amount
from cleaned_data
where discount_applied = 'yes' and purchased_amount >
(select 
avg(purchased_amount) as avg_amount
from cleaned_data);

-- Which are the top 5 products with the highest average review rating.
select top 5 item_purchased,
round(avg(review_rating),2)
from cleaned_data
group by item_purchased
order by round(avg(review_rating),2) desc;

-- Compare the average Purchase Amounts between Standard and Express Shipping?
select avg(purchased_amount) as avg_amount,
shipping_type
from cleaned_data
where shipping_type in ('Standard','Express')
group by shipping_type
 
 -- Do subscribed customers spend more?
 -- Compare average spend and total revenue between subscribers and non-subscribers?
 select subscription_status,
 count(customer_id) as total_custoemr,
 avg(purchased_amount) as avg_spend,
 sum(purchased_amount) as total_revenue
 from cleaned_data
 group by subscription_status
 order by total_revenue, avg_spend desc;

 -- Which 5 products have the highest percentage of purchase with discounts applied?
 select top 5
 item_purchased,
 round(100*sum(case when discount_applied = 'Yes' then 1 else 0 end)/count(*),2) as discount_rate
 from cleaned_data
 group by item_purchased
 order by discount_rate desc;

 -- Segment customers into New, Returning and loyal based on their total number of previous purchase.
 -- Show the count of each segment.
 with customer_type as(
 select customer_id, previous_purchases,
 case
     when previous_purchases = 1 then 'New'
     when previous_purchases between 2 and 10 then 'Returning'
     else 'Loyal'
end as customer_segment
from cleaned_data
)

select customer_segment,
count(*) as total_customers
from customer_type
group by customer_segment;

-- What are the top 3 most purchased products within each category?
with item_counts as (
select category, item_purchased,
count(customer_id) as total_orders,
row_number () over (partition by category order by count(customer_id)  desc) as item_rank
from cleaned_data 
group by category, item_purchased
)
select category, item_purchased, item_rank, total_orders
from item_counts
where item_rank <=3;

-- Are customers who are repeat buyers (more than 5 previous purchase) also likely to subscribe?
select subscription_status,
count(customer_id) as repeat_buyers
from cleaned_data
where previous_purchases > 5
group by subscription_status;

-- What is the revenue contribution of each age group?
select age_group,
sum(purchased_amount) as total_revenue
from cleaned_data
group by age_group
order by total_revenue desc;